class Channel {
  std::mutex m_; std::vector<std::function<void(const Event&)>> subs_;
public:
  void subscribe(std::function<void(const Event&)> fn) {
    std::lock_guard<std::mutex> g(m_); subs_.push_back(std::move(fn));
  }
  void publish(const Event& e) {
    std::vector<std::function<void(const Event&)>> snap;
    { std::lock_guard<std::mutex> g(m_); snap = subs_; }   // snapshot under lock
    for (auto& fn : snap) fn(e);                           // dispatch unlocked
  }
};

